function check_laxity(state S):
  for each task 𝜏_i in Active(S):
    if ttd_S(𝜏_i) - rct_S(𝜏_i) < 0:
      return False  // Infeasible
  return True // Potentially feasible

function check_worst_laxity(state S):
  for each task 𝜏_i in Active(S):
    extra_budget = 0
    if 𝜏_i.L == 'HI' and S.cri == 'LO':
      extra_budget = 𝜏_i.C(HI) - 𝜏_i.C(LO)
    current_laxity = ttd_S(𝜏_i) - rct_S(𝜏_i)
    worst_laxity = current_laxity - extra_budget
    if worst_laxity < 0:
      return False  // Infeasible
  return True // Potentially feasible

function check_demand_bound(state S):
  for each task 𝜏_i in Active(S):
    deadline = ttd_S(𝜏_i)
    demand = dbf_cri_S_S(deadline)
    if deadline < demand:
      return False  // Infeasible
  return True // Potentially feasible

function check_hi_demand_bound(state S):
  for each task 𝜏_i in Active(S):
    deadline = ttd_S(𝜏_i)
    demand = dbf_HI_S(deadline)
    if deadline < demand:
      return False  // Infeasible
  return True // Potentially feasible
